# Generated by build.py from recipe.yml for recipe s3-upload-a-large-object-in-parts. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'store/backups' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'upload-in-parts.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh upload-in-parts.sh FILE URL PART-BYTES [curl options...]`n# Uploads FILE to the object URL as an S3 multipart upload: starts the upload, puts FILE in parts of`n# PART-BYTES (the last may be shorter), then completes it with each part's number and ETag. Prints`n# each step's status. When a step is refused it prints the S3 error code, aborts the upload so the`n# server drops the parts it holds, and exits 1.`nfile=`$1 url=`$2 size=`$3`nshift 3`nwork=`$file.parts`nrm -rf `"`$work`" && mkdir `"`$work`"`ncode() { sed -n 's/.*<Code>\([^<]*\)<\/Code>.*/\1/p' `"`$work/answer`"; }`nabort() {`n  echo `"refused: `$(code)`"`n  echo `"abort: `$(curl -s `"`$@`" -X DELETE -o /dev/null -w `"%{http_code}`" `"`$url?uploadId=`$id`")`"`n  exit 1`n}`nstatus=`$(curl -s `"`$@`" -X POST -o `"`$work/answer`" -w `"%{http_code}`" `"`$url?uploads`")`necho `"initiate: `$status`"`nid=`$(sed -n 's/.*<UploadId>\([^<]*\)<\/UploadId>.*/\1/p' `"`$work/answer`")`nif [ `"`$status`" != 200 ]; then echo `"refused: `$(code)`"; exit 1; fi`nsplit -b `"`$size`" `"`$file`" `"`$work/part.`"`nn=0`nprintf '<CompleteMultipartUpload>' > `"`$work/complete.xml`"`nfor part in `"`$work`"/part.*; do`n  n=`$((n + 1))`n  got=`$(curl -s `"`$@`" -T `"`$part`" -o `"`$work/answer`" -w `"%{http_code} %header{etag}`" `"`$url?partNumber=`$n&uploadId=`$id`")`n  echo `"part `$n: `${got%% *}`"`n  case `"`$got`" in 200*) ;; *) abort `"`$@`" ;; esac`n  printf '<Part><PartNumber>%s</PartNumber><ETag>%s</ETag></Part>' `"`$n`" `"`${got#* }`" >> `"`$work/complete.xml`"`ndone`nprintf '</CompleteMultipartUpload>' >> `"`$work/complete.xml`"`nstatus=`$(curl -s `"`$@`" --data-binary `"@`$work/complete.xml`" -o `"`$work/answer`" -w `"%{http_code}`" `"`$url?uploadId=`$id`")`necho `"complete: `$status`"`nif [ `"`$status`" != 200 ]; then abort `"`$@`"; fi`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:*.s3.us-east-1.amazonaws.com"'
cmd /c 'openssl rand -out backup.tar 11000000'
cmd /c 'openssl rand -out huge.tar 13000000'
$server0 = Start-Process surl -ArgumentList '--directory', 'store', '--cert', 'server.pem', '--key', 'server.key', '--user', 'AKIAIOSFODNN7EXAMPLE:s3cret', '--allow-uploads', '--max-filesize', '12M', 's3://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh upload-in-parts.sh backup.tar https://backups.s3.us-east-1.amazonaws.com/backup.tar 5242880 --max-time 60 --cacert server.pem --connect-to ::127.0.0.1:8080 --aws-sigv4 aws:amz:us-east-1:s3 -u AKIAIOSFODNN7EXAMPLE:s3cret } finally { Stop-Process $server0 }
